// Generated by Go tasking.TriggerFromComponent and accepted by the core native
// target decoder. This is structural inference context, not an origin signature.
private func nativePersonComponent() throws -> JSONValue {
    let originalBody = Data(#"{"algorithm":"camera-ankle-two-observation-tracking","algorithm_version":"1","ambiguous":false,"clock_domain":"simulation:run-native","covariance":[0.1,0,0,0.1],"current":[{"calibration_revision":"test-cal","calibration_sha256":"eeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeee","capture_sequence":1,"captured_unix_ns":1767225600000000000,"covariance":[0.1,0,0,0.1],"image":{"content_type":"image/png","sha256":"cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc","size":100},"member_index":0,"model_id":"test-model","model_sha256":"dddddddddddddddddddddddddddddddddddddddddddddddddddddddddddddddd","model_version":"1","physical_until":"2026-01-01T00:00:04Z","position_xz":[1.25,0],"proof":{"key":{"tenant":"tenant","site":"office","entity":"sensor/people-front","type":"wendy.sensor.capture.v1","source":{"device":"gateway-a","app":"com.example.people","service":"people-front","stream":"people-front"}},"version":{"epoch":2,"sequence":4},"envelope_sha256":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","record_sha256":"bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb"},"sample_id":"run-native/people-front/1","sample_time":"2026-01-01T00:00:00Z","scene_boot_id":"test-scene","sensor_id":"people-front","simulation_anchor_unix_ns":1767225600000000000,"valid_until":"2026-01-01T00:00:01Z"}],"frame":{"id":"office-floor","revision":"office-frame-v1"},"motion_known":false,"observed_at":"2026-01-01T00:00:00Z","position_xz":[1.25,0],"revision":1,"run_id":"run-native","schema":"wendy.person.track.v1","track_id":"anonymous-1","valid_until":"2026-01-01T00:00:01Z"}"#.utf8)
    var component = try JSONValue.decode(Data(#"{"key":{"tenant":"tenant","site":"office","entity":"run-native/track/anonymous-1","type":"wendy.inference.result.v1","source":{"device":"gateway-a","app":"com.example.people","service":"people","stream":"tracks"}},"version":{"epoch":3,"sequence":9},"frame":{"id":"office-floor","revision":"office-frame-v1"},"timing":{"sample_time":"2026-01-01T00:00:00Z","clock_domain":"simulation:run-native","error_known":true,"error_bound_ns":0,"age_hint_ns":0},"ttl_ns":1000000000,"provenance":{"origin":"inferred","app_version":"world-live-people-v1","model_id":"camera-ankle-two-observation-tracking","model_version":"1","inputs":[{"id":"sha256:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","origin":"simulated","simulation":{"run_id":"run-native","scenario_version":"test-only","seed":1,"clock_domain":"simulation:run-native"}}]},"payload":{"version":1,"result_schema":"wendy.person.track.v1","result_json":"","inputs":[{"key":{"tenant":"tenant","site":"office","entity":"sensor/people-front","type":"wendy.sensor.capture.v1","source":{"device":"gateway-a","app":"com.example.people","service":"people-front","stream":"people-front"}},"version":{"epoch":2,"sequence":4},"envelope_sha256":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","record_sha256":"bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb"}],"retain_until_unix_ms":1767225660000},"tombstone":false}"#.utf8)).object!
    var payload = component["payload"]!.object!
    payload["result_json"] = .string(originalBody.base64EncodedString()); component["payload"] = .object(payload)
    return .object(component)
}
private let nativePersonComponentDigest = "76cd883e2208d04d6ba4d96160b3256b27b08a1dd22e0a049d83df764239744e"

private func reorderedNativeTrigger() throws -> MissionNativeTrigger {
    let component = try nativePersonComponent()
    // JSONEncoder's sorted wrapper/reference order differs from the Go producer
    // struct order, but is valid RawMessage and must not be reconstructed.
    let payload = try component["payload"]!.encoded()
    let bytes = try NativeTriggerWire.component(component, rawPayload: payload)
    let raw = GoAuthorityJSON.object([("sha256", GoAuthorityJSON.string(WorldCredentials.digest(bytes))), ("component", bytes)])
    return try MissionNativeTrigger(canonical: raw, fixedTarget: [1.25, 0.2, 0], originalEnvelopeSHA256: String(repeating: "f", count: 64))
}

private final class RawMissionHTTPState: @unchecked Sendable {
    private let lock = NSLock()
    private var instruction: Data?
    private var attempts = 0
    private var stopped = false
    func respond(_ request: LoopbackServer.Request) throws -> LoopbackServer.Response {
        lock.lock(); defer { lock.unlock() }
        if request.path == "/v1/tasks" {
            if let instruction { guard instruction == request.body else { return .init(status: 409) } }
            instruction = request.body; attempts += 1
            if attempts == 1 { return .init(status: 503) } // Accepted, reply lost.
        }
        if request.path == "/v1/tasks/stop" { stopped = true }
        guard let instruction else { return .init(status: 404) }
        let spec = try MissionRawJSON.field(instruction, path: ["payload"])
        let status = try JSONValue.object(["Version": .integer(stopped ? 2 : 1), "Phase": .string(stopped ? "canceled" : "running"), "Reason": .string("")]).encoded()
        return .init(body: GoAuthorityJSON.object([("spec", spec), ("proof", instruction), ("status", status)]) + Data("\n".utf8))
    }
}

private actor MissionFixtureTransport: MissionTransport {
    let instruction: Data
    let stop: Data
    var submitted: [Data] = []
    var fail = false
    var mismatched = false
    var delayed = false
    init(_ instruction: Data, stop: Data) { self.instruction = instruction; self.stop = stop }
    func setFailure(_ value: Bool) { fail = value }
    func setMismatch(_ value: Bool) { mismatched = value }
    func setDelayed(_ value: Bool) { delayed = value }
    func beginMissionOperation() async throws -> UInt64 { 1 }
    func prepareInstruction(draft: MissionDraft, operation: UInt64) async throws -> Data { instruction }
    func submit(instruction: Data, operation: UInt64) async throws -> JSONValue {
        submitted.append(instruction)
        if delayed { try await Task.sleep(for: .milliseconds(300)) }
        if fail { throw URLError(.networkConnectionLost) }
        return try record()
    }
    func status(taskID: String) async throws -> JSONValue { try record() }
    func prepareStop(taskID: String) async throws -> Data { stop }
    func submitStop(instruction: Data) async throws -> JSONValue { try record(phase: "canceled", version: 2) }
    func record(phase: String = "running", version: Int64 = 1) throws -> JSONValue {
        let proof = try JSONValue.decode(instruction)
        var spec = proof["payload"]!.object!
        if mismatched { spec["id"] = .string("other-task") }
        return .object(["spec": .object(spec), "proof": proof, "status": .object(["Version": .integer(version), "Phase": .string(phase), "Reason": .string("")]), "authorization_until_unix_ms": proof["expires_at_unix_ms"]!])
    }
}

@MainActor final class MissionTests: XCTestCase {
    func testRawTriggerPreservesReorderedPayloadAndCanonicalOuterFields() throws {
        let producer = try nativeTrigger(), reordered = try reorderedNativeTrigger()
        XCTAssertNotEqual(reordered.sha256, producer.sha256)
        XCTAssertEqual(try JSONValue.decode(reordered.canonical)["component"], try JSONValue.decode(producer.canonical)["component"])
        let rawPayload = try MissionRawJSON.field(reordered.canonical, path: ["component", "payload"])
        XCTAssertEqual(rawPayload, try nativePersonComponent()["payload"]!.encoded())
        XCTAssertEqual(try JSONDecoder().decode(MissionNativeTrigger.self, from: JSONEncoder().encode(reordered)), reordered)
        let draft = try nativeDraft(trigger: reordered), context = try context()
        let spec = try context.spec(draft: draft, deadline: fixture()["spec"]!["not_after_unix_ms"]!.int!)
        XCTAssertEqual(try MissionRawJSON.field(spec, path: ["trigger"]), reordered.canonical)
        XCTAssertEqual(try MissionProof.specBytes(spec), spec)
        let producerSpec = try context.spec(draft: nativeDraft(), deadline: fixture()["spec"]!["not_after_unix_ms"]!.int!)
        XCTAssertEqual(try MissionProof.specBytes(JSONValue.decode(producerSpec)), producerSpec)
        // A typed-only response cannot guess discarded original ordering.
        XCTAssertThrowsError(try MissionProof.specBytes(JSONValue.decode(spec)))
        let text = String(decoding: reordered.canonical, as: UTF8.self)
        for altered in [text + " ", text.replacingOccurrences(of: "\"payload\":{", with: "\"payload\":{ "),
                        text.replacingOccurrences(of: "\"result_schema\":", with: "\"version\":1,\"result_schema\":"),
                        text.replacingOccurrences(of: "\"sha256\":\"" + reordered.sha256, with: "\"sha256\":\"" + String(repeating: "0", count: 64))] {
            XCTAssertThrowsError(try Data(altered.utf8).mapNativeTrigger(target: reordered.fixedTarget))
        }
        let escaped = rawPayload.range(of: Data("\"inputs\"".utf8))!
        var unusual = rawPayload
        unusual.replaceSubrange(escaped, with: Data(#""\u0069nputs""#.utf8))
        let component = try NativeTriggerWire.component(nativePersonComponent(), rawPayload: unusual)
        let canonical = GoAuthorityJSON.object([("sha256", GoAuthorityJSON.string(WorldCredentials.digest(component))), ("component", component)])
        XCTAssertEqual(try canonical.mapNativeTrigger(target: reordered.fixedTarget).canonical, canonical)
        XCTAssertThrowsError(try MissionRawJSON.field(Data(#"{"a":{"x":1,"\u0078":2}}"#.utf8), path: ["a"]))
        XCTAssertThrowsError(try MissionRawJSON.field(Data(("{\"a\":" + String(repeating: "[", count: 40) + "0" + String(repeating: "]", count: 40) + "}").utf8), path: ["a"]))
    }

    func testRawTriggerSignedHTTPJournalRetryStatusStopAndUnknownTaskReopen() async throws {
        let fixture = try fixture(), trigger = try reorderedNativeTrigger(), state = RawMissionHTTPState()
        let proposalView = try nativeProposalView(digest: trigger.sha256)
        let server = try LoopbackServer { request in
            do {
                if request.path == "/v1/tasks/clock" { return try missionClockFixtureResponse(request, fixture: fixture) }
                if request.path == "/v1/tasks/catalog" { return .init(body: try JSONValue.object(["assignee": fixture["spec"]!["assignee"]!, "domain": .string("simulation"), "run_id": .string("run-native"), "types": .array([.object(["type": .string("wendy.nav.inspect.v1"), "class": .string("MOVE")])])]).encoded()) }
                if request.path == "/v1/proposals/native-trigger-proposal" { return .init(body: try proposalView.encoded()) }
                return try state.respond(request)
            } catch { return .init(status: 500) }
        }
        defer { server.stop() }
        let credentials = try MissionCredentials(data: JSONValue.object(["url": .string(server.url.absoluteString), "audience": .string("node-1"), "grant": fixture["operator_grant"]!, "private_key": fixture["operator_private_key"]!, "allow_insecure_simulation": .bool(true)]).encoded())
        let client = try MissionClient(credentials: credentials, context: fixture["control_context"]!, pins: pins())
        let proposal = try MissionProposal(view: proposalView, context: client.context, credentials: credentials)
        let draft = try MissionDraft(id: "raw-order-task", target: trigger.fixedTarget, durationMS: 30_000, context: client.context, proposal: proposal, trigger: trigger)
        let dir = FileManager.default.temporaryDirectory.appendingPathComponent("raw-mission-" + UUID().uuidString)
        defer { try? FileManager.default.removeItem(at: dir) }
        let journal = try MissionJournal(directory: dir, credentials: credentials, context: client.context)
        try await journal.saveDraft(draft)
        do { try await journal.signAndSend(id: draft.id, using: client); XCTFail("lost reply became success") } catch {}
        let saved = await journal.entries(); XCTAssertEqual(saved.first?.state, .uncertain)
        let instruction = try XCTUnwrap(saved.first?.instruction)
        XCTAssertEqual(try MissionRawJSON.field(instruction, path: ["payload", "trigger"]), trigger.canonical)
        let reopened = try MissionJournal(directory: dir, credentials: credentials, context: client.context)
        try await reopened.retry(id: draft.id, using: client)
        XCTAssertEqual(server.requests.filter { $0.path == "/v1/tasks" }.map(\.body), [instruction, instruction])
        try await reopened.reconcile(id: draft.id, using: client)
        try await reopened.stop(id: draft.id, using: client)
        let stopped = await reopened.entries(); XCTAssertEqual(stopped.first?.phase, "canceled")
        let restored = try MissionJournal(directory: dir, credentials: credentials, context: client.context)
        let history = await restored.entries(); XCTAssertEqual(history.first?.draft.trigger?.canonical, trigger.canonical)
        XCTAssertEqual(history.first?.instruction, instruction)
        let otherDir = dir.appendingPathComponent("independent")
        let independent = try MissionJournal(directory: otherDir, credentials: credentials, context: client.context)
        try await independent.stopAny(taskID: draft.id, using: client)
        let stops = await independent.stopEntries(), stop = try XCTUnwrap(stops.first)
        XCTAssertEqual(stop.state, "acknowledged")
        let original = try XCTUnwrap(stop.originalRecordJSON)
        XCTAssertEqual(try MissionRawJSON.field(original, path: ["spec", "trigger"]), trigger.canonical)
        let restoredIndependent = try MissionJournal(directory: otherDir, credentials: credentials, context: client.context)
        let reopenedStops = await restoredIndependent.stopEntries(); XCTAssertEqual(reopenedStops.first?.originalRecordJSON, original)
        XCTAssertThrowsError(try MissionProof.stoppedRecord(stop.record!, taskID: draft.id, credentials: credentials, context: client.context))
        var changed = try JSONValue.decode(original).object!, spec = changed["spec"]!.object!
        spec["target"] = .array([.number(0), .number(0.2), .number(0)]); changed["spec"] = .object(spec)
        XCTAssertThrowsError(try MissionProof.stoppedRecord(.object(changed), taskID: draft.id, credentials: credentials, context: client.context, originalJSON: original))
    }

    func testRawTriggerActualGoHandoffsAndCanonicalSpec() throws {
        let environment = ProcessInfo.processInfo.environment
        guard let old = environment["WORLD_RAW_TRIGGER_HANDOFF"], let producer = environment["WORLD_PRODUCER_TRIGGER_HANDOFF"],
              let specPath = environment["WORLD_CANONICAL_SPEC"] else { throw XCTSkip("Retained Go interoperability files are supplied by the qualification command") }
        for path in [old, producer] {
            let handoff = try JSONValue.decode(Data(contentsOf: URL(fileURLWithPath: path)))
            let input = handoff["mission_input"]!, canonical = Data(base64Encoded: input["trigger_json"]!.string!)!
            let trigger = try MissionNativeTrigger(canonical: canonical, fixedTarget: MissionWire.vector(input["target"]), originalEnvelopeSHA256: input["envelope_sha256"]!.string!)
            XCTAssertEqual(trigger.canonical, canonical); XCTAssertEqual(trigger.sha256, input["trigger_sha256"]?.string)
            XCTAssertEqual(trigger.fixedTarget[1], 0.65)
            XCTAssertEqual(try JSONDecoder().decode(MissionNativeTrigger.self, from: JSONEncoder().encode(trigger)), trigger)
        }
        let spec = try Data(contentsOf: URL(fileURLWithPath: specPath))
        XCTAssertEqual(try MissionProof.specBytes(spec), spec)
    }

