    func testGoCanonicalContextSpecInstructionsAndTransport() throws {
        let v = try fixture(), c = try credentials(), context = try context()
        XCTAssertEqual(context.canonical, Data(v["control_context_canonical"]!.string!.utf8))
        XCTAssertEqual(context.digest, v["control_context_sha256"]?.string)
        let spec = try context.spec(draft: draft(), deadline: v["spec"]!["not_after_unix_ms"]!.int!)
        XCTAssertEqual(spec, Data(v["spec_canonical"]!.string!.utf8))
        for (operation, name) in [("mission", "instruction"), ("stop", "stop_instruction")] {
            let value = v[name]!, payload = operation == "mission" ? spec : GoAuthorityJSON.object([("task_id", GoAuthorityJSON.string("mission-native"))])
            let signed = try c.signInstruction(operation: operation, payload: payload, issuedAtUnixMS: value["issued_at_unix_ms"]!.int!, expiresAtUnixMS: value["expires_at_unix_ms"]!.int!)
            let actual = try JSONValue.decode(signed)
            let signingBytes = Data(v[name + "_signing_bytes"]!.string!.utf8)
            XCTAssertTrue(c.key.publicKey.isValidSignature(Data(base64Encoded: actual["signature"]!.string!)!, for: signingBytes))
            XCTAssertTrue(c.key.publicKey.isValidSignature(Data(base64Encoded: value["signature"]!.string!)!, for: signingBytes))
            var expectedFields = value.object!, actualFields = actual.object!
            expectedFields.removeValue(forKey: "signature"); actualFields.removeValue(forKey: "signature")
            XCTAssertEqual(actualFields, expectedFields)
            try c.verifyInstruction(signed, operation: operation, payload: payload, issued: value["issued_at_unix_ms"]!.int!, expires: value["expires_at_unix_ms"]!.int!)
        }
        let body = Data(v["instruction_canonical"]!.string!.utf8), transport = v["transport"]!
        let signed = try c.signedAuthorization(operation: "mission", body: body, nonce: transport["nonce"]!.string!, issuedAtUnixMS: transport["issued_at_unix_ms"]!.int!, lifetimeMS: 60_000)
        var expectedFields = transport.object!, actualFields = try JSONValue.decode(signed).object!
        let signature = Data(base64Encoded: actualFields.removeValue(forKey: "signature")!.string!)!
        expectedFields.removeValue(forKey: "signature"); XCTAssertEqual(actualFields, expectedFields)
        XCTAssertTrue(c.key.publicKey.isValidSignature(signature, for: Data(v["transport_signing_bytes"]!.string!.utf8)))
    }
    func testGoClockProofPurposeAndPins() throws {
        let v = try fixture(), c = try credentials(), pins = try pins(), request = Data(v["clock_request_canonical"]!.string!.utf8)
        let signed = try MissionClockWire.request(credentials: c, pins: pins, purpose: "mission", nonce: String(repeating: "ab", count: 32))
        let actualRequest = try JSONValue.decode(signed)
        XCTAssertEqual(actualRequest["request"], v["clock_request"]?["request"])
        XCTAssertTrue(c.key.publicKey.isValidSignature(Data(base64Encoded: actualRequest["signature"]!.string!)!, for: Data(v["clock_request_signing_bytes"]!.string!.utf8)))
        try MissionClockWire.verify(observation: v["clock_observation"]!, request: request, credentials: c, pins: pins, purpose: "mission")
        XCTAssertThrowsError(try MissionClockWire.verify(observation: v["clock_observation"]!, request: request, credentials: c, pins: pins, purpose: "stop"))
        for field in ["nonce", "run_id", "clock_domain", "gateway_principal", "operator_key_sha256", "request_sha256", "reference"] {
            var wrapper = v["clock_observation"]!.object!, obs = wrapper["observation"]!.object!
            obs[field] = .string("tampered"); wrapper["observation"] = .object(obs)
            XCTAssertThrowsError(try MissionClockWire.verify(observation: .object(wrapper), request: request, credentials: c, pins: pins, purpose: "mission"), field)
        }
    }
    func testClockRejectsSuspendRollbackRestartAndLongRTT() throws {
        let observation = try fixture()["clock_observation"]!
        let received = AnnotationClockReading(bootID: "test", nanoseconds: 1_000_000_000)
        let anchor = MissionClockAnchor(observation: observation, received: received, rttNS: 20_000_000, purpose: "mission")
        let sample = observation["observation"]!["sample_unix_ms"]!.int!
        let interval = try anchor.interval(at: received)
        XCTAssertEqual(interval.lowerUnixMS, sample - 2); XCTAssertEqual(interval.upperUnixMS, sample + 22)
        XCTAssertNoThrow(try anchor.interval(at: .init(bootID: "test", nanoseconds: 6_000_000_000)))
        XCTAssertThrowsError(try anchor.interval(at: .init(bootID: "test", nanoseconds: 6_000_000_001)))
        XCTAssertThrowsError(try anchor.interval(at: .init(bootID: "test", nanoseconds: 999_999_999)))
        XCTAssertThrowsError(try anchor.interval(at: .init(bootID: "new", nanoseconds: 1_000_000_000)))
        XCTAssertThrowsError(try MissionClockAnchor(observation: observation, received: received, rttNS: 2_000_000_001, purpose: "mission").interval(at: received))
    }
