    func testDurableUncertainDeliveryReopenExactRetryAndMismatch() async throws {
        let dir = FileManager.default.temporaryDirectory.appendingPathComponent("mission-journal-" + UUID().uuidString)
        defer { try? FileManager.default.removeItem(at: dir) }
        let v = try fixture(), credentials = try credentials(), context = try context(), draft = try draft()
        let client = MissionFixtureTransport(Data(v["instruction_canonical"]!.string!.utf8), stop: Data(v["stop_instruction_canonical"]!.string!.utf8))
        let journal = try MissionJournal(directory: dir, credentials: credentials, context: context)
        try await journal.saveDraft(draft)
        let restoredDraft = try MissionJournal(directory: dir, credentials: credentials, context: context)
        let draftEntries = await restoredDraft.entries(); XCTAssertEqual(draftEntries.first?.state, .draft); XCTAssertNil(draftEntries.first?.instruction)
        await client.setFailure(true)
        do { try await journal.signAndSend(id: draft.id, using: client); XCTFail("uncertain response accepted") } catch {}
        let before = await journal.entries(); XCTAssertEqual(before.first?.state, .uncertain)
        let reopened = try MissionJournal(directory: dir, credentials: credentials, context: context)
        let reopenedEntries = await reopened.entries(); XCTAssertEqual(reopenedEntries.first?.instruction, before.first?.instruction)
        let sends = await client.submitted; XCTAssertEqual(sends.count, 1)
        await client.setFailure(false); await client.setMismatch(true)
        do { try await reopened.reconcile(id: draft.id, using: client); XCTFail("mismatched status accepted") } catch {}
        await client.setMismatch(false)
        try await reopened.retry(id: draft.id, using: client)
        let allSends = await client.submitted; XCTAssertEqual(allSends.count, 2); XCTAssertEqual(allSends[0], allSends[1])
        let delivered = await reopened.entries(); XCTAssertEqual(delivered.first?.state, .delivered)
        try await reopened.stop(id: draft.id, using: client)
        let stopped = await reopened.entries(); XCTAssertEqual(stopped.first?.phase, "canceled"); XCTAssertEqual(stopped.first?.stopState, "acknowledged")
        let restoreStop = try MissionJournal(directory: dir, credentials: credentials, context: context)
        let restoredStops = await restoreStop.entries(); XCTAssertEqual(restoredStops.first?.stopInstruction, stopped.first?.stopInstruction)
        let otherDir = dir.appendingPathComponent("other-profile")
        let independent = try MissionJournal(directory: otherDir, credentials: credentials, context: context)
        try await independent.stopAny(taskID: draft.id, using: client)
        let anyStops = await independent.stopEntries(); XCTAssertEqual(anyStops.first?.state, "acknowledged")
        let owned = await independent.entries(); XCTAssertTrue(owned.isEmpty)
        let restoredIndependent = try MissionJournal(directory: otherDir, credentials: credentials, context: context)
