private final class SuspendedMissionClock: @unchecked Sendable {
    private let lock = NSLock()
    private var count: Int64 = 0
    func read() -> AnnotationClockReading {
        lock.lock(); defer { lock.unlock() }; count += 1
        // The proof is valid when received, then the device sleeps before signing.
        return AnnotationClockReading(bootID: "suspend-test", nanoseconds: 1_000_000_000 + count * 1_000_000 + (count >= 4 ? 6_000_000_000 : 0))
    }
}

