        let proof: JSONValue = .object(["version": .integer(1), "grant": grant, "audience": .string(c.audience), "operation": .string("propose"), "body_sha256": .string(hash), "nonce": .string(nonce), "issued_at_unix_ms": .integer(now), "expires_at_unix_ms": .integer(now + 60_000), "signature": .string(try c.key.signature(for: message).base64EncodedString())])
        return .object(["expired": .bool(false), "record": .object(["proposal": try JSONValue.decode(body), "body": .string(body.base64EncodedString()), "body_sha256": .string(hash), "class": .string("MOVE"), "principal": grantBody["principal"]!, "kind": grantBody["kind"]!, "source": grantBody["source"]!, "grant_id": grantBody["id"]!, "accepted_at_unix_ms": .integer(now + 10), "proof": proof])])
    }
    func nativeDraft(trigger: MissionNativeTrigger? = nil) throws -> MissionDraft {
        let t = try trigger ?? nativeTrigger(), c = try context()
        let p = try MissionProposal(view: nativeProposalView(digest: t.sha256), context: c, credentials: credentials())
        return try MissionDraft(id: "native-trigger-task", target: t.fixedTarget, durationMS: 30_000, context: c, proposal: p, trigger: t)
    }
