    func testNativeTriggerRejectsSubstitutionAndKeepsCommissionedRoute() throws {
        let trigger = try nativeTrigger(), context = try context(), c = try credentials()
        for mode in ["type", "age", "digest", "schema"] {
            var object = try JSONValue.decode(trigger.canonical).object!, component = object["component"]!.object!
            if mode == "type" { var key = component["key"]!.object!; key["type"] = .string("wendy.hazard.v1"); component["key"] = .object(key) }
            if mode == "age" { var timing = component["timing"]!.object!; timing["age_hint_ns"] = .integer(1); component["timing"] = .object(timing) }
            if mode == "schema" { var payload = component["payload"]!.object!; payload["result_schema"] = .string("unknown"); component["payload"] = .object(payload) }
            if mode == "digest" { object["sha256"] = .string(String(repeating: "0", count: 64)) }
            object["component"] = .object(component)
            XCTAssertThrowsError(try NativeTriggerWire.trigger(.object(object)).mapNativeTrigger(target: trigger.fixedTarget), mode)
        }
        XCTAssertThrowsError(try nativeTrigger(target: [1, 0.2, 0]))
        let wrongFloor = try nativeTrigger(target: [1.25, 0, 0])
        XCTAssertThrowsError(try wrongFloor.validateDraft(in: context))
        for digest in [nil, String(repeating: "0", count: 64)] as [String?] {
            let proposal = try MissionProposal(view: nativeProposalView(digest: digest), context: context, credentials: c)
            XCTAssertThrowsError(try MissionDraft(target: trigger.fixedTarget, durationMS: 30_000, context: context, proposal: proposal, trigger: trigger))
        }
        let p = try MissionProposal(view: nativeProposalView(digest: trigger.sha256), context: context, credentials: c)
        XCTAssertThrowsError(try MissionDraft(target: trigger.fixedTarget, durationMS: 30_000, context: context, proposal: p))
        XCTAssertThrowsError(try MissionDraft(target: [1, 0.2, 0], durationMS: 30_000, context: context, proposal: p, trigger: trigger))
        var other = try nativePersonComponent().object!, key = other["key"]!.object!
        key["site"] = .string("other"); other["key"] = .object(key)
        XCTAssertThrowsError(try nativeTrigger(.object(other)).validate(context: context))
    }
