    func testNativeTriggerJournalReopenExactRetryAndStop() async throws {
        let dir = FileManager.default.temporaryDirectory.appendingPathComponent("native-trigger-journal-" + UUID().uuidString)
        defer { try? FileManager.default.removeItem(at: dir) }
        let v = try fixture(), c = try credentials(), context = try context(), draft = try nativeDraft(), now = v["now_unix_ms"]!.int!
        let spec = try context.spec(draft: draft, deadline: now + 30_000)
        let instruction = try c.signInstruction(operation: "mission", payload: spec, issuedAtUnixMS: now, expiresAtUnixMS: now + 30_000)
        let stop = try c.signInstruction(operation: "stop", payload: GoAuthorityJSON.object([("task_id", GoAuthorityJSON.string(draft.id))]), issuedAtUnixMS: now, expiresAtUnixMS: now + 5_000)
        let client = MissionFixtureTransport(instruction, stop: stop), journal = try MissionJournal(directory: dir, credentials: c, context: context)
        try await journal.saveDraft(draft); await client.setFailure(true)
        do { try await journal.signAndSend(id: draft.id, using: client); XCTFail("lost reply became success") } catch {}
        let reopened = try MissionJournal(directory: dir, credentials: c, context: context)
        let before = await reopened.entries(); XCTAssertEqual(before.first?.draft.trigger, draft.trigger)
        XCTAssertEqual(before.first?.instruction, instruction)
        await client.setFailure(false); try await reopened.retry(id: draft.id, using: client)
        let sends = await client.submitted; XCTAssertEqual(sends, [instruction, instruction])
        try await reopened.stop(id: draft.id, using: client)
        let entries = await reopened.entries(); XCTAssertEqual(entries.first?.phase, "canceled")
        try MissionProof.stoppedRecord(entries.first!.record!, taskID: draft.id, credentials: c, context: context)
        var changed = entries.first!.record!.object!, specValue = changed["spec"]!.object!
        specValue["target"] = .array([.number(0), .number(0.2), .number(0)]); changed["spec"] = .object(specValue)
        XCTAssertThrowsError(try MissionProof.stoppedRecord(.object(changed), taskID: draft.id, credentials: c, context: context))
    }
    func testNativeHTTPRechecksExactProposalBeforeSigning() async throws {
        let v = try fixture(), draft = try nativeDraft()
        for replace in [false, true] {
            let proposal = try nativeProposalView(digest: replace ? String(repeating: "0", count: 64) : draft.trigger!.sha256)
            let server = try LoopbackServer { request in
                do {
                    if request.path == "/v1/tasks/clock" { return try missionClockFixtureResponse(request, fixture: v) }
                    if request.path == "/v1/tasks/catalog" { return .init(body: try JSONValue.object(["assignee": v["spec"]!["assignee"]!, "domain": .string("simulation"), "run_id": .string("run-native"), "types": .array([.object(["type": .string("wendy.nav.inspect.v1"), "class": .string("MOVE")])])]).encoded()) }
                    if request.path == "/v1/proposals/native-trigger-proposal" { return .init(body: try proposal.encoded()) }
                    return .init(status: 404)
                } catch { return .init(status: 500) }
            }
            defer { server.stop() }
            let c = try MissionCredentials(data: JSONValue.object(["url": .string(server.url.absoluteString), "audience": .string("node-1"), "grant": v["operator_grant"]!, "private_key": v["operator_private_key"]!, "allow_insecure_simulation": .bool(true)]).encoded())
            let client = try MissionClient(credentials: c, context: v["control_context"]!, pins: pins()), operation = try await client.beginMissionOperation()
            do {
                let instruction = try await client.prepareInstruction(draft: draft, operation: operation)
                XCTAssertFalse(replace)
                XCTAssertEqual(try JSONValue.decode(instruction)["payload"]?["trigger"], try JSONValue.decode(draft.trigger!.canonical))
            } catch { XCTAssertTrue(replace, "original proposal refused: \(error)") }
            XCTAssertFalse(server.requests.contains { $0.path == "/v1/tasks" })
        }
    }
