private extension Data {
    func mapNativeTrigger(target: [Double]) throws -> MissionNativeTrigger {
        try MissionNativeTrigger(canonical: self, fixedTarget: target, originalEnvelopeSHA256: String(repeating: "f", count: 64))
    }
}
private extension MissionNativeTrigger {
    func validateDraft(in context: MissionContext) throws {
        try context.validate(target: fixedTarget, durationMS: 30_000)
    }
}

extension MissionTests {
    func testClockBusyRetriesUseNewNoncesWithoutRetryingMotion() async throws {
        let v = try fixture(), counter = MissionTestCounter()
        let server = try LoopbackServer { request in
            if counter.next() <= 2 { return .init(status: 429) }
            return (try? missionClockFixtureResponse(request, fixture: v)) ?? .init(status: 500)
        }
        defer { server.stop() }
        let c = try MissionCredentials(data: JSONValue.object(["url": .string(server.url.absoluteString), "audience": .string("node-1"), "grant": v["operator_grant"]!, "private_key": v["operator_private_key"]!, "allow_insecure_simulation": .bool(true)]).encoded())
        let client = try MissionClient(credentials: c, context: v["control_context"]!, pins: pins())
        let instruction = try await client.prepareStop(taskID: "clock-busy-stop")
        XCTAssertEqual(try JSONValue.decode(instruction)["operation"]?.string, "stop")
        XCTAssertEqual(server.requests.count, 3)
        let nonces = try server.requests.map { try JSONValue.decode($0.body)["request"]!["nonce"]!.string! }
        XCTAssertEqual(Set(nonces).count, 3)
        XCTAssertTrue(server.requests.allSatisfy { $0.path == "/v1/tasks/clock" })
    }
    func testClockBackoffStopsOnLifecycleInvalidation() async throws {
        let v = try fixture()
        let server = try LoopbackServer { _ in .init(status: 429) }
        defer { server.stop() }
        let c = try MissionCredentials(data: JSONValue.object(["url": .string(server.url.absoluteString), "audience": .string("node-1"), "grant": v["operator_grant"]!, "private_key": v["operator_private_key"]!, "allow_insecure_simulation": .bool(true)]).encoded())
        let client = try MissionClient(credentials: c, context: v["control_context"]!, pins: pins())
        async let action = client.catalog()
        for _ in 0..<50 {
            if !server.requests.isEmpty { break }
            try await Task.sleep(for: .milliseconds(5))
        }
        client.setMissionActive(false)
        do { _ = try await action; XCTFail("invalidated clock retry continued") } catch {}
        XCTAssertEqual(server.requests.count, 1)
    }
}

